import json
n=22
grid=[[4]*n for _ in range(n)]
# (top, left, border, interior)
objs=[(3,0,8,6),(16,0,8,2),(12,5,8,7),(9,12,2,9),(5,17,2,1),(17,17,2,6)]
for r0,c0,b,i in objs:
    for dr in range(5):
        for dc in range(5):
            grid[r0+dr][c0+dc]=i if 1<=dr<=3 and 1<=dc<=3 else b
print(json.dumps(grid,separators=(',',':')))
